CREATE COLUMN TABLE "TEST_AP"."OWTT" ("WTTypeId" INTEGER CS_INT NOT NULL , "WTType" NVARCHAR(10) NOT NULL , "WTThresh" DECIMAL(21,6) CS_FIXED, "LogInstanc" INTEGER CS_INT DEFAULT 0, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("WTTypeId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OWTT_WT_TYPE" ON "TEST_AP"."OWTT" ( "WTType" ASC )